#include <string.h>
#include <stdio.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_timer.h"
#include "esp_heap_caps.h"
#include "esp_event.h"
#include "esp_netif.h"
#include "esp_wifi.h"
#include "nvs.h"
#include "sentinel.h"
static portMUX_TYPE mux=portMUX_INITIALIZER_UNLOCKED;
static sentinel_snapshot_t state;
static uint32_t seconds_now(void){return (uint32_t)(esp_timer_get_time()/1000000);}
const char *sentinel_security(unsigned v){return v==SEC_OPEN?"ABIERTA":v==SEC_WEP?"WEP/PRIV":v==SEC_WPA?"WPA":"RSN/WPA2+";}
void sentinel_address(const uint8_t b[6],char out[18]){snprintf(out,18,"%02x:%02x:%02x:%02x:%02x:%02x",b[0],b[1],b[2],b[3],b[4],b[5]);}
static void save_baseline(void){nvs_handle_t h;if(nvs_open_from_partition("sentinel_nvs","guard",NVS_READWRITE,&h)==ESP_OK){nvs_set_u8(h,"set",state.baseline_set);if(state.baseline_set){nvs_set_str(h,"ssid",state.baseline_ssid);nvs_set_blob(h,"bssid",state.baseline_bssid,6);nvs_set_u8(h,"sec",state.baseline_security);nvs_set_u8(h,"chan",state.baseline_channel);}nvs_commit(h);nvs_close(h);}}
static void add_event(uint8_t kind,const ap_t *ap,uint8_t channel,int8_t rssi){unsigned slot=state.event_count<EVENT_CAP?state.event_count++:EVENT_CAP-1;if(slot==EVENT_CAP-1&&state.event_count==EVENT_CAP)memmove(&state.events[0],&state.events[1],sizeof(state.events[0])*(EVENT_CAP-1));sentinel_event_t *e=&state.events[slot];memset(e,0,sizeof(*e));e->kind=kind;e->channel=channel;e->rssi=rssi;e->when=seconds_now();if(ap){strlcpy(e->ssid,ap->ssid,sizeof(e->ssid));memcpy(e->bssid,ap->bssid,6);}}
static security_t parse_security(const uint8_t *frame,unsigned len){bool privacy=frame[34]&0x10,rsn=false,wpa=false;for(unsigned p=36;p+2<=len;){unsigned n=frame[p+1];if(p+2+n>len)break;if(frame[p]==48)rsn=true;if(frame[p]==221&&n>=4&&frame[p+2]==0&&frame[p+3]==0x50&&frame[p+4]==0xf2&&frame[p+5]==1)wpa=true;p+=2+n;}return rsn?SEC_RSN:wpa?SEC_WPA:privacy?SEC_WEP:SEC_OPEN;}
static bool parse_ssid(const uint8_t *frame,unsigned len,char out[33],uint8_t *tag_channel){out[0]=0;*tag_channel=0;for(unsigned p=36;p+2<=len;){unsigned id=frame[p],n=frame[p+1];if(p+2+n>len){if(len-p<=4)break;return false;}if(id==0){unsigned copy=n<32?n:32,visible=0;for(unsigned i=0;i<copy;i++){uint8_t c=frame[p+2+i];out[i]=c>=32&&c<=126?(char)c:'?';if(c)visible++;}out[visible?copy:0]=0;}else if(id==3&&n==1)*tag_channel=frame[p+2];p+=2+n;}return true;}
static void receive(void *buffer,wifi_promiscuous_pkt_type_t type){if(type!=WIFI_PKT_MGMT)return;const wifi_promiscuous_pkt_t *packet=buffer;const uint8_t *f=packet->payload;unsigned len=packet->rx_ctrl.sig_len;if(len<24)return;uint8_t subtype=f[0]&0xf0;uint32_t now=seconds_now();portENTER_CRITICAL(&mux);state.frames++;if(packet->rx_ctrl.channel<14)state.channel_frames[packet->rx_ctrl.channel]++;if(subtype==0xc0||subtype==0xa0){if(subtype==0xc0)state.deauth++;else state.disassoc++;state.last_deauth=now;if(!state.event_count||now-state.events[state.event_count-1].when>2)add_event(3,NULL,packet->rx_ctrl.channel,packet->rx_ctrl.rssi);portEXIT_CRITICAL(&mux);return;}portEXIT_CRITICAL(&mux);if((subtype!=0x80&&subtype!=0x50)||len<36)return;
 char ssid[33];uint8_t tagged;if(!parse_ssid(f,len,ssid,&tagged)){portENTER_CRITICAL(&mux);state.malformed++;portEXIT_CRITICAL(&mux);return;}uint8_t channel=tagged?tagged:packet->rx_ctrl.channel;security_t security=parse_security(f,len);const uint8_t *bssid=&f[16];
 portENTER_CRITICAL(&mux);state.beacons++;unsigned index=state.count;for(unsigned i=0;i<state.count;i++)if(!memcmp(state.aps[i].bssid,bssid,6)){index=i;break;}bool fresh=index==state.count;if(fresh){if(state.count==AP_CAP){state.dropped++;portEXIT_CRITICAL(&mux);return;}state.count++;ap_t *a=&state.aps[index];memset(a,0,sizeof(*a));memcpy(a->bssid,bssid,6);a->first=now;strlcpy(a->ssid,ssid,sizeof(a->ssid));a->security=security;a->channel=channel;add_event(1,a,channel,packet->rx_ctrl.rssi);if(state.baseline_set&&ssid[0]&&!strcmp(ssid,state.baseline_ssid)&&security!=state.baseline_security){state.security_mismatches++;add_event(2,a,channel,packet->rx_ctrl.rssi);}}
 ap_t *a=&state.aps[index];if(ssid[0])strlcpy(a->ssid,ssid,sizeof(a->ssid));a->security=security;a->channel=channel;a->rssi=packet->rx_ctrl.rssi;a->last=now;a->reports++;portEXIT_CRITICAL(&mux);
}
static void hopper(void *unused){uint8_t channel=1;while(1){bool run;portENTER_CRITICAL(&mux);run=state.running;portEXIT_CRITICAL(&mux);if(run){esp_wifi_set_channel(channel,WIFI_SECOND_CHAN_NONE);portENTER_CRITICAL(&mux);state.channel=channel;portEXIT_CRITICAL(&mux);channel=channel==13?1:channel+1;}vTaskDelay(pdMS_TO_TICKS(run?280:200));}}
void sentinel_start(void){wifi_init_config_t cfg=WIFI_INIT_CONFIG_DEFAULT();ESP_ERROR_CHECK(esp_netif_init());ESP_ERROR_CHECK(esp_event_loop_create_default());ESP_ERROR_CHECK(esp_wifi_init(&cfg));ESP_ERROR_CHECK(esp_wifi_set_storage(WIFI_STORAGE_RAM));ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_NULL));ESP_ERROR_CHECK(esp_wifi_start());wifi_country_t country={.cc="ES",.schan=1,.nchan=13,.policy=WIFI_COUNTRY_POLICY_MANUAL};ESP_ERROR_CHECK(esp_wifi_set_country(&country));wifi_promiscuous_filter_t filter={.filter_mask=WIFI_PROMIS_FILTER_MASK_MGMT};ESP_ERROR_CHECK(esp_wifi_set_promiscuous_filter(&filter));ESP_ERROR_CHECK(esp_wifi_set_promiscuous_rx_cb(receive));state.running=true;ESP_ERROR_CHECK(esp_wifi_set_promiscuous(true));
 nvs_handle_t h;if(nvs_open_from_partition("sentinel_nvs","guard",NVS_READONLY,&h)==ESP_OK){uint8_t v;if(nvs_get_u8(h,"set",&v)==ESP_OK&&v){size_t n=sizeof(state.baseline_ssid),b=6;state.baseline_set=nvs_get_str(h,"ssid",state.baseline_ssid,&n)==ESP_OK&&nvs_get_blob(h,"bssid",state.baseline_bssid,&b)==ESP_OK;nvs_get_u8(h,"sec",&state.baseline_security);nvs_get_u8(h,"chan",&state.baseline_channel);}nvs_close(h);}assert(xTaskCreate(hopper,"channel_hopper",3072,NULL,5,NULL)==pdPASS);}
void sentinel_snapshot(sentinel_snapshot_t *out){portENTER_CRITICAL(&mux);*out=state;portEXIT_CRITICAL(&mux);out->uptime=seconds_now();out->heap=esp_get_free_heap_size();}
void sentinel_next(void){portENTER_CRITICAL(&mux);if(state.count)state.selected=(state.selected+1)%state.count;portEXIT_CRITICAL(&mux);}
bool sentinel_select(unsigned id){portENTER_CRITICAL(&mux);bool ok=id<state.count;if(ok)state.selected=id;portEXIT_CRITICAL(&mux);return ok;}
bool sentinel_clear(void){portENTER_CRITICAL(&mux);memset(state.aps,0,sizeof(state.aps));memset(state.events,0,sizeof(state.events));state.count=state.selected=state.event_count=0;state.security_mismatches=state.dropped=0;portEXIT_CRITICAL(&mux);return true;}
bool sentinel_set_running(bool enabled){esp_err_t e=esp_wifi_set_promiscuous(enabled);if(e==ESP_OK){portENTER_CRITICAL(&mux);state.running=enabled;portEXIT_CRITICAL(&mux);}return e==ESP_OK;}
bool sentinel_baseline_selected(void){portENTER_CRITICAL(&mux);bool ok=state.selected<state.count;if(ok){ap_t *a=&state.aps[state.selected];state.baseline_set=true;strlcpy(state.baseline_ssid,a->ssid,sizeof(state.baseline_ssid));memcpy(state.baseline_bssid,a->bssid,6);state.baseline_security=a->security;state.baseline_channel=a->channel;}portEXIT_CRITICAL(&mux);if(ok)save_baseline();return ok;}
bool sentinel_forget_baseline(void){portENTER_CRITICAL(&mux);bool had=state.baseline_set;state.baseline_set=false;memset(state.baseline_ssid,0,sizeof(state.baseline_ssid));portEXIT_CRITICAL(&mux);save_baseline();return had;}
